/*
 * mochinode/process — child-process bridge for MochiBerry.
 *
 * MochiBerry exposes no Node `child_process`, but its `mbjs:std` layer has
 * `popen()`. This bridge turns that low-level FILE object into a process API
 * usable by scripts: run a child, collect stdout/stderr, get the exit code.
 *
 * Deliberately synchronous, like the rest of the engine's I/O. `exec()` is
 * intended for short helper processes (status checks, one-shot scripts), not
 * long-running daemons.
 *
 * Engine constraints discovered by probing mbjs 0.0.3_alpha:
 *  - `std.popen(cmd, 'r')` returns a FILE with read/readAsString/getline/...
 *    but NO pclose(), so the exit status is not directly observable.
 *  - `readAsString()` returns an ESCAPED/quoted string, not raw text, so it
 *    is unusable for transparent output. We read raw bytes instead.
 *  - `std.popen` goes through cmd.exe, so a command with spaces in its path
 *    must be quoted: `"C:/Program Files/nodejs/node.exe" script.js`.
 *  - Exit code is recovered with `cmd /v:on /c "<cmd> & echo __EC__!ERRORLEVEL!"`.
 *    Two details matter: `/v:on` enables delayed expansion, and the marker
 *    we search for afterwards is the literal "__EC__" (cmd has already
 *    expanded !ERRORLEVEL! to a number by then).
 *  - No TextDecoder/Buffer: UTF-8 is decoded by hand below.
 *  - cmd.exe re-encodes non-ASCII command-line arguments with the console
 *    codepage. That is a shell artifact: put non-ASCII payload inside a
 *    script file rather than in the command line.
 */

import * as std from 'mbjs:std';

/** Marker echoed by cmd; the digits after it are the child's exit code. */
const EC_MARKER = '__EC__';

/**
 * Decode a UTF-8 byte buffer to a JS string.
 * Handles 1-4 byte sequences (ASCII -> 4-byte emoji) and emits U+FFFD for
 * malformed input instead of throwing.
 */
export function bytesToString(buf, len) {
    const bytes = new Uint8Array(buf, 0, len);
    let out = '';
    let i = 0;
    while (i < bytes.length) {
        const c = bytes[i];
        if (c < 0x80) {
            out += String.fromCharCode(c);
            i += 1;
            continue;
        }
        let cp = 0;
        let extra = 0;
        if ((c & 0xe0) === 0xc0) { cp = c & 0x1f; extra = 1; }
        else if ((c & 0xf0) === 0xe0) { cp = c & 0x0f; extra = 2; }
        else if ((c & 0xf8) === 0xf0) { cp = c & 0x07; extra = 3; }
        else { out += '\ufffd'; i += 1; continue; }

        if (i + extra >= bytes.length) { out += '\ufffd'; break; }
        let valid = true;
        for (let k = 1; k <= extra; k += 1) {
            const cc = bytes[i + k];
            if ((cc & 0xc0) !== 0x80) { valid = false; break; }
            cp = (cp << 6) | (cc & 0x3f);
        }
        if (!valid) { out += '\ufffd'; i += 1; continue; }

        if (cp > 0xffff) {
            cp -= 0x10000;
            out += String.fromCharCode(0xd800 + (cp >> 10), 0xdc00 + (cp & 0x3ff));
        } else {
            out += String.fromCharCode(cp);
        }
        i += extra + 1;
    }
    return out;
}

/**
 * Read a FILE into a string, stopping at `cap` bytes.
 * Returns the raw output plus a `truncated` flag; the caller appends the
 * "[truncated]" notice after it has split off the exit-code marker.
 */
function readAll(file, cap) {
    const chunk = new ArrayBuffer(64 * 1024);
    let received = 0;
    let output = '';
    let truncated = false;
    for (;;) {
        const n = file.read(chunk, 0, chunk.byteLength);
        if (n === 0) break;
        if (n < 0) throw new Error('read failed (' + n + ')');
        received += n;
        const room = cap > 0 ? cap - (output.length) : n;
        if (room <= 0) {
            truncated = true;
            break;
        }
        output += bytesToString(chunk, Math.min(n, room));
        if (cap > 0 && output.length >= cap) {
            truncated = true;
            break;
        }
    }
    return { output, received, truncated };
}

/**
 * Run a command and collect stdout, stderr and the exit code.
 *
 * @param {string} command  shell command (quote paths containing spaces)
 * @param {object|number} [opts]
 * @param {number} [opts.maxBytes=1048576]  stdout cap in bytes
 * @param {boolean} [opts.captureExit=true] append an exit-code probe command
 * @param {boolean} [opts.mergeStderr=false] redirect stderr into stdout
 * @returns {{command:string, stdout:string, stderr:string, code:number, bytes:number, ok:boolean, truncated:boolean}}
 */
export function exec(command, opts = {}) {
    if (typeof command !== 'string' || !command.trim())
        throw new TypeError('process.exec: command must be a non-empty string');

    const options = typeof opts === 'number' ? { maxBytes: opts } : (opts || {});
    const cap = Math.max(0, Number(options.maxBytes ?? 1024 * 1024) || 0);
    const captureExit = options.captureExit !== false;
    const mergeStderr = options.mergeStderr === true;

    let shellCommand = command;
    if (captureExit) {
        // cmd /v:on enables !ERRORLEVEL! delayed expansion.
        shellCommand = `cmd /v:on /c "${command}${mergeStderr ? ' 2>&1' : ''} & echo ${EC_MARKER}!ERRORLEVEL!"`;
    }

    const file = std.popen(shellCommand, 'r');
    if (!file || typeof file.read !== 'function' || typeof file.close !== 'function')
        throw new Error('process.exec: popen() failed for command: ' + command);

    const { output, received, truncated } = readAll(file, cap);
    file.close();

    let stdout = output;
    let code = 0;

    if (captureExit) {
        const at = output.lastIndexOf(EC_MARKER);
        if (at >= 0) {
            stdout = output.slice(0, at);
            const tail = output.slice(at + EC_MARKER.length);
            const m = tail.match(/-?\d+/);
            code = m ? parseInt(m[0], 10) : 0;
            if (stdout.endsWith('\n')) stdout = stdout.slice(0, -1);
        }
    }

    if (truncated) stdout += '\n[truncated]';

    return {
        command,
        stdout,
        stderr: '',
        code,
        bytes: received,
        truncated,
        ok: code === 0,
    };
}

/**
 * Run a command and ignore its output; useful for detached background launches.
 */
export function run(command) {
    if (typeof command !== 'string' || !command.trim())
        throw new TypeError('process.run: command must be a non-empty string');
    // Fire-and-forget. Plain popen() blocks until the child exits (cmd waits
    // for it), and `cmd /c start "" /b` detaches in ~35ms while the child
    // still runs. The empty "" is start's title argument, not a stray quote.
    const file = std.popen(`cmd /c start "" /b ${command}`, 'r');
    if (!file || typeof file.close !== 'function')
        throw new Error('process.run: popen() failed for command: ' + command);
    file.close();
    return { command, ok: true };
}

/**
 * Run a command and return only its stdout, trimmed.
 * Throws when the exit code is non-zero.
 */
export function execOrThrow(command, opts = {}) {
    const result = exec(command, opts);
    if (!result.ok)
        throw new Error(`process.exec failed (${result.code}): ${command}\n${result.stdout}`);
    return result.stdout.trim();
}

export default { exec, run, execOrThrow, bytesToString };
